-- MI-22 canonical ERP integration ports and versioned accounting events.
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_erp_port(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),property_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,target_system VARCHAR(24) NOT NULL,adapter_key VARCHAR(64) NOT NULL,contract_version VARCHAR(32) NOT NULL,credential_reference VARCHAR(180),status VARCHAR(24) NOT NULL DEFAULT 'CONFIGURATION_REQUIRED',capabilities JSONB NOT NULL DEFAULT '[]'::jsonb,last_health_at TIMESTAMPTZ,UNIQUE(property_id,target_system,adapter_key));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_domain_event(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),property_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_property(id) ON DELETE RESTRICT,event_type VARCHAR(80) NOT NULL,event_version INTEGER NOT NULL,aggregate_type VARCHAR(48) NOT NULL,aggregate_id UUID NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(),payload JSONB NOT NULL,correlation_id UUID NOT NULL,idempotency_key VARCHAR(128) NOT NULL UNIQUE,created_by UUID);
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_erp_delivery(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_domain_event(id) ON DELETE RESTRICT,target_system VARCHAR(24) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),external_reference VARCHAR(180),last_error TEXT,delivered_at TIMESTAMPTZ,UNIQUE(event_id,target_system),CONSTRAINT ck_hospitality_erp_delivery_status CHECK(status IN('PENDING','PROCESSING','DELIVERED','FAILED','DEAD_LETTER')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_accounting_event(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),domain_event_id UUID NOT NULL UNIQUE REFERENCES "{{TENANT_SCHEMA}}".hospitality_domain_event(id) ON DELETE RESTRICT,accounting_event_type VARCHAR(64) NOT NULL,schema_version INTEGER NOT NULL,source_document_type VARCHAR(48) NOT NULL,source_document_id UUID NOT NULL,business_date DATE NOT NULL,currency CHAR(3) NOT NULL,amount NUMERIC(16,2) NOT NULL,dimensions JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',posting_reference UUID,reversal_of_id UUID REFERENCES "{{TENANT_SCHEMA}}".hospitality_accounting_event(id) ON DELETE RESTRICT,CONSTRAINT ck_hospitality_accounting_status CHECK(status IN('PENDING','POSTED','RECONCILED','FAILED','REVERSED')));
CREATE TABLE IF NOT EXISTS "{{TENANT_SCHEMA}}".hospitality_erp_reconciliation(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),delivery_id UUID NOT NULL REFERENCES "{{TENANT_SCHEMA}}".hospitality_erp_delivery(id) ON DELETE RESTRICT,local_amount NUMERIC(16,2),remote_amount NUMERIC(16,2),status VARCHAR(16) NOT NULL,details JSONB NOT NULL DEFAULT '{}'::jsonb,reconciled_by UUID,reconciled_at TIMESTAMPTZ,CONSTRAINT ck_hospitality_erp_recon_status CHECK(status IN('MATCHED','MISMATCH','RESOLVED')));
CREATE INDEX IF NOT EXISTS ix_hospitality_erp_delivery_queue ON "{{TENANT_SCHEMA}}".hospitality_erp_delivery(status,next_attempt_at);
